const CG_LOCALES = {en:'en-GB',de:'de-DE',es:'es-ES',fr:'fr-FR',pt:'pt-PT',pl:'pl-PL',ro:'ro-RO',nl:'nl-NL',it:'it-IT',zh:'zh-CN',hi:'hi-IN',ja:'ja-JP'};
const CG_ALIASES = {
  sent:'sent',unpaid:'unpaid',partially_paid:'partlyPaid',payment_pending:'paymentPending',overdue:'overdue',paid:'paid',draft:'draft',high:'high',medium:'medium',low:'low'
};
function cgDetectedLanguage(){for(const value of navigator.languages||[navigator.language]){const code=String(value).split('-')[0].toLowerCase();if(CG_LANGUAGES[code])return code;}return 'en';}
let cgLanguage = (()=>{try{const saved=localStorage.getItem('cg_language');return saved && CG_LANGUAGES[saved] ? saved : cgDetectedLanguage();}catch(e){return cgDetectedLanguage();}})();
function cgT(key,values={}){
 let result=(CG_TRANSLATIONS[cgLanguage]||CG_TRANSLATIONS.de)[key]||CG_TRANSLATIONS.en[key]||key;
 for(const [name,v] of Object.entries(values))result=result.replaceAll('{'+name+'}',String(v));
 return result;
}
function cgDate(input){if(!input)return '—';const d=new Date(String(input).slice(0,10)+'T12:00:00');return Number.isNaN(d.valueOf())?String(input):new Intl.DateTimeFormat(CG_LOCALES[cgLanguage],{day:'2-digit',month:'short',year:'numeric'}).format(d);}
function cgMoney(currency,val){return `${currency} ${Number(val||0).toLocaleString(CG_LOCALES[cgLanguage],{minimumFractionDigits:2,maximumFractionDigits:2})}`;}
function cgStatus(value){const key=CG_ALIASES[String(value||'').toLowerCase()];return key?cgT(key):String(value||'');}
function cgDescription(row){const fromDemo = (row.source==='synthetic demo'||row.source==='synthetic'||row.source==='synthetic preview');return fromDemo && CG_DEMO_DESCRIPTIONS[cgLanguage]?.[row.number] || row.description || '';}
function cgFlagImage(code){
 const img=document.createElement('img');
 img.className='flag-image';
 img.src=CG_FLAG_IMAGES[code] || CG_FLAG_IMAGES.de;
 img.width=32;img.height=22;img.alt='';img.setAttribute('aria-hidden','true');
 img.decoding='async';img.draggable=false;
 return img;
}
function cgFlag(flag){
 const raw=String(flag||'');const overdue=raw.match(/^(\d+) days? overdue$/i);
 if(overdue)return cgT('daysOverdue',{n:overdue[1]});
 if(/potential duplicate/i.test(raw))return cgT('possibleDuplicate');
 if(/unusual amount or age/i.test(raw))return cgT('unusualFlag');
 return raw;
}
function cgFlags(row){return (row.flags||[]).map(cgFlag).join(' · ');}
function cgRenderMenu(){
 const root=document.getElementById('languageMenu');if(!root)return;
 root.innerHTML='';
 [...Object.entries(CG_LANGUAGES)].sort((a,b)=>new Intl.Collator('de',{sensitivity:'base'}).compare(a[1].name,b[1].name)).forEach(([code,info])=>{
 const b=document.createElement('button');b.type='button';b.className='lang-option';b.setAttribute('role','menuitemradio');b.setAttribute('aria-checked',String(code===cgLanguage));
 b.dataset.lang=code;b.lang=code;
 const flag=cgFlagImage(code);
 const label=document.createElement('span');label.textContent=info.name;label.lang=code;label.dir='auto';
 const check=document.createElement('span');check.className='lang-check';check.textContent=code===cgLanguage?'✓':'';
 b.append(flag,label,check);b.addEventListener('click',()=>cgSelectLanguage(code));root.append(b);
 });
}
function cgCloseMenu(){const menu=document.getElementById('languageMenu'),b=document.getElementById('languageButton');if(!menu||!b)return;menu.hidden=true;b.setAttribute('aria-expanded','false');}
function cgSelectLanguage(lang){
 if(!CG_LANGUAGES[lang])return;
 cgLanguage=lang;try{localStorage.setItem('cg_language',lang);}catch(e){}
 cgApplyLanguage();cgCloseMenu();
 if(typeof cgOnLanguageChanged==='function')cgOnLanguageChanged();
 document.getElementById('languageButton')?.focus();
}
function cgApplyLanguage(){
 const html=document.documentElement;html.lang=cgLanguage;html.dir='ltr';
 document.title='Cashflow Guardian — '+cgT('financialIntel');
 document.querySelectorAll('[data-i18n]').forEach(el=>{el.textContent=cgT(el.dataset.i18n);});
 document.querySelectorAll('[data-i18n-placeholder]').forEach(el=>{el.placeholder=cgT(el.dataset.i18nPlaceholder);});
 document.querySelectorAll('[data-i18n-aria-label]').forEach(el=>{el.setAttribute('aria-label',cgT(el.dataset.i18nAriaLabel));});
 const b=document.getElementById('languageButton');if(b){b.replaceChildren(cgFlagImage(cgLanguage));b.setAttribute('aria-label',cgT('languageAria')+': '+CG_LANGUAGES[cgLanguage].name);b.title=CG_LANGUAGES[cgLanguage].name;}
 const m=document.getElementById('languageMenu');if(m)m.setAttribute('aria-label',cgT('languages'));
 cgRenderMenu();
}
function cgInitLanguage(){
 cgApplyLanguage();
 const btn=document.getElementById('languageButton'),menu=document.getElementById('languageMenu');if(!btn||!menu)return;
 btn.addEventListener('click',()=>{menu.hidden=!menu.hidden;btn.setAttribute('aria-expanded',String(!menu.hidden));if(!menu.hidden)menu.querySelector('[aria-checked="true"]')?.focus();});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!menu.hidden){cgCloseMenu();btn.focus();}if(!menu.hidden&&(e.key==='ArrowDown'||e.key==='ArrowUp')){e.preventDefault();const all=[...menu.querySelectorAll('button')];let i=all.indexOf(document.activeElement);all[(i+(e.key==='ArrowDown'?1:-1)+all.length)%all.length].focus();}});
 document.addEventListener('pointerdown',e=>{if(!menu.hidden&&!e.target.closest('.language-switcher'))cgCloseMenu();});
}
